# >>> STATIC
_static_F() {
    cat <<-'ARGCEOF'
	0	notify as previewer
	1	notify as explorer
ARGCEOF
}

_static_T() {
    cat <<-'ARGCEOF'
	a	apparent disk usage, how large the file appears to be, can be bigger than actual disk usage in sparse files
	d	disk usage, amount of data taken on disk, a multiple of the block size
	e	extension of the file
	r	reverse the current order (not available with -T)
	s	size of file, amount of data stored in the file
	t	time, this depends on the currently selected time type which can be changed using the T key
	v	version, sorts by filename while treating digit characters numerically
ARGCEOF
}
# <<< STATIC

# >>> CHOICES
# Bookmark keys from NNN_BMS (key:location pairs separated by ';').
_choice_bookmark() {
    local entry key location
    local -a entries
    IFS=';' read -r -a entries <<< "${NNN_BMS:-}"
    for entry in "${entries[@]}"; do
        [[ -n $entry ]] || continue
        key=${entry%%:*}
        location=${entry#*:}
        if [[ $location == "$entry" ]]; then
            printf '%s\n' "$key"
        else
            printf '%s\t%s\n' "$key" "$location"
        fi
    done
}

# Plugin keys from NNN_PLUG (key:plugin pairs separated by ';').
_choice_plugin() {
    local entry key plugin
    local -a entries
    IFS=';' read -r -a entries <<< "${NNN_PLUG:-}"
    for entry in "${entries[@]}"; do
        [[ -n $entry ]] || continue
        key=${entry%%:*}
        plugin=${entry#*:}
        if [[ $plugin == "$entry" ]]; then
            printf '%s\n' "$key"
        else
            printf '%s\t%s\n' "$key" "$plugin"
        fi
    done
}

# Session names in ${XDG_CONFIG_HOME:-$HOME/.config}/nnn/sessions; @ is the auto session.
_choice_session() {
    local dir="${XDG_CONFIG_HOME:-$HOME/.config}/nnn/sessions" file
    printf '@\tauto session\n'
    for file in "$dir"/*; do
        [[ -f $file ]] || continue
        printf '%s\n' "${file##*/}"
    done
}
# <<< CHOICES

command eval "$(argc --argc-eval "$0" "$@")"
